// Turn everything into one short text list for Claude
const items = $input.all().map((i, idx) => {
  const j = i.json;
  if (j.start) return { id: `cal-${idx}`, source: 'calendar', title: j.summary, start: j.start.dateTime || j.start.date, attendees: (j.attendees||[]).map(a=>a.email), description: (j.description||'').slice(0,500) };
  if (j.channel || j.permalink) return { id: `slack-${idx}`, source: 'slack', channel: j.channel?.name, user: j.username || j.user, text: (j.text||'').slice(0,800) };
  return { id: `email-${idx}`, source: 'email', from: j.From || j.from, subject: j.Subject || j.subject, snippet: (j.snippet||'').slice(0,800) };
});
return [{ json: { items_text: JSON.stringify(items, null, 1), count: items.length } }];

// Turn Claude's JSON into one readable digest
const raw = ($json.content || []).map(c => c.text || '').join('');
let data;
try { data = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
catch (e) { return [{ json: { digest: '*Morning brief*
Could not read Claude's answer. Raw output:
' + raw } }]; }
const groups = { needs_me_today: [], can_wait: [], fyi: [] };
for (const it of data.items || []) if (groups[it.category]) groups[it.category].push(it);
let out = '*Morning brief* (drafts only, nothing has been sent)

*Needs you today*
';
for (const it of groups.needs_me_today) out += `- [${it.source}] ${it.summary}
  Draft/prep: ${it.draft_or_prep || 'n/a'}
`;
out += '
*Can wait*
' + groups.can_wait.map(i => `- ${i.summary}`).join('
');
out += '

*FYI*
' + groups.fyi.map(i => `- ${i.summary}`).join('
');
out += '

Review, edit and send any drafts yourself.';
return [{ json: { digest: out } }];
